<script>import{t}from'../logic/i18n.js';import{getAllSlugs}from'../logic/wiki.js';let{lang='fa',isOpen=false,isMobile=false,currentSlug='home',sq='',onNavigate,onToggle,onSearch}=$props();const pages=$derived(getAllSlugs());const filtered=$derived(sq?pages.filter(p=>(p.titles[lang]||p.titles.fa||p.slug).toLowerCase().includes(sq.toLowerCase())):pages);const isLtr=$derived(lang==='en');let noT=$state(false);$effect(()=>{const _=isLtr;if(!isOpen){noT=true;requestAnimationFrame(()=>requestAnimationFrame(()=>noT=false))}});function hi(e){if(onSearch)onSearch(e.target.value)}function clr(){if(onSearch)onSearch('')}</script>{#if isMobile}<div class="so" class:so--o={isOpen} role="button" tabindex="-1" onclick={()=>onToggle&&onToggle()} onkeydown={(e)=>{if(e.key==='Escape'||e.key==='Enter')onToggle&&onToggle()}}></div><aside class="sb sb--m" class:sb--o={isOpen} class:sb--ltr={isLtr} class:sb--no-t={noT}><div class="mh"><div class="mhd"><span class="mht">{t(lang,'siteTitle')}</span><button class="mc" onclick={()=>onToggle&&onToggle()} aria-label={t(lang,'closeSidebar')}><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="20" height="20"><path d="M18 6 6 18M6 6l12 12"/></svg></button></div><div class="ms"><svg class="msi" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/></svg><input type="text" class="ms2" placeholder={t(lang,'search')} value={sq} oninput={hi}/>{#if sq}<button class="msx" onclick={clr}><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="14" height="14"><path d="M18 6 6 18M6 6l12 12"/></svg></button>{/if}</div></div>{#if filtered.length===0}<div class="me"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" width="48" height="48"><circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/><line x1="8" y1="8" x2="8.01" y2="8"/><line x1="14" y1="14" x2="14.01" y2="14"/></svg><p>{t(lang,'noResults')}</p></div>{:else}<nav class="sn">{@render pagesList(filtered)}</nav>{/if}</aside>{/if}{#if !isMobile}<div class="sw"><aside class="sb sb--d sb--ltr" class:sb--do={isOpen}><div class="sh"><span class="st2">{t(lang,'allPages')}</span></div><nav class="sn">{@render pagesList(pages)}</nav></aside><div class="st st--ltr" role="button" tabindex="0" onclick={()=>onToggle&&onToggle()} onkeydown={(e)=>{if(e.key==='Enter'||e.key===' ')onToggle&&onToggle()}}><svg class="st-arr" class:st-arr--o={isOpen} viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="16" height="16"><path d="M9 18l6-6-6-6"/></svg><span class="tl">{t(lang,'allPages')}</span></div></div>{/if}{#snippet pagesList(list)}<ul class="pl">{#each list as page(page.slug)}<li><button class="pli" class:pli--a={currentSlug===page.slug} onclick={()=>{if(onNavigate)onNavigate(page.slug);if(isMobile&&onToggle)onToggle()}}><span class="pi2">{page.titles[lang]?.[0]||page.titles.fa?.[0]||page.slug[0]}</span><span class="pt2">{page.titles[lang]||page.titles.fa||page.slug}</span></button></li>{/each}</ul>{/snippet}<style>.so{position:fixed;inset:0;background:rgba(0,0,0,0.5);z-index:90;opacity:0;pointer-events:none;transition:opacity var(--transition-normal);backdrop-filter:blur(2px)}.so--o{opacity:1;pointer-events:auto}.sb--m{position:fixed;top:0;bottom:0;right:0;width:300px;max-width:88vw;background:var(--color-bg-primary);z-index:95;display:flex;flex-direction:column;box-shadow:-8px 0 30px rgba(0,0,0,0.15);transform:translateX(100%);pointer-events:none;transition:transform 280ms cubic-bezier(0.4,0,0.2,1)}.sb--m.sb--o{transform:translateX(0);pointer-events:auto}.sb--m.sb--ltr{right:auto;left:0;box-shadow:8px 0 30px rgba(0,0,0,0.15);transform:translateX(-100%)}.sb--m.sb--ltr.sb--o{transform:translateX(0)}.sb--no-t{transition:none!important}.mh{padding:1.125rem 1rem;border-bottom:1px solid var(--color-border);flex-shrink:0;display:flex;flex-direction:column;gap:0.75rem}.mhd{display:flex;align-items:c