-muted);transition:background var(--transition-fast),color var(--transition-fast)}.st:hover{background:var(--color-bg-hover);color:var(--color-accent)}.st:not(.st--ltr){border-left:1px solid var(--color-border)}.st--ltr{border-right:1px solid var(--color-border)}.st--ltr .st-arr{transform:scaleX(-1)}.st-arr{transition:transform var(--transition-normal)}.st-arr--o{transform:rotate(180deg)}.st--ltr .st-arr--o{transform:scaleX(-1) rotate(180deg)}.tl{writing-mode:vertical-rl;font-size:var(--font-size-xs);font-weight:600;letter-spacing:0.05em;text-transform:uppercase}.sh{display:flex;align-items:center;justify-content:space-between;padding:1rem;border-bottom:1px solid var(--color-border);flex-shrink:0}.st2{font-weight:600;font-size:var(--font-size-sm);color:var(--color-text-secondary);text-transform:uppercase;letter-spacing:0.05em}.sn{flex:1;overflow-y:auto;padding:0.4rem 0}.pl{list-style:none;padding:0;margin:0}.pli{display:flex;align-items:center;gap:0.85rem;width:100%;padding:0.7rem 1rem;border:none;background:none;color:var(--color-text-secondary);font-family:var(--font-body);font-size:var(--font-size-sm);cursor:pointer;transition:all var(--transition-fast);white-space:nowrap}.pli:hover{background:var(--color-bg-hover);color:var(--color-text-primary)}.pli--a{background:var(--color-bg-hover);color:var(--color-text-primary);font-weight:600;border-right:3px solid var(--color-accent)}.pi2{width:32px;height:32px;flex-shrink:0;display:flex;align-items:center;justify-content:center;background:var(--color-accent-bg);color:var(--color-accent);border-radius:var(--radius-md);font-size:var(--font-size-xs);font-weight:700;text-transform:uppercase}.pt2{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}</style>